from pathlib import Path
s=Path('start_v2_tier1.py').read_text()
s=s.replace("'v2_tier1_01'","'v2_tier1_02'")
s=s.replace("return image,visible,labels,dict(","return image,visible,labels,full,dict(")
s=s.replace("nn.Conv2d(3,16,3,2,1),nn.ReLU(),nn.Conv2d(16,24,3,2,1),nn.ReLU(),nn.Conv2d(24,48,3,2,1),nn.ReLU()","nn.Conv2d(3,24,3,2,1),nn.BatchNorm2d(24),nn.ReLU(),nn.Conv2d(24,32,3,2,1),nn.BatchNorm2d(32),nn.ReLU(),nn.Conv2d(32,48,3,2,1),nn.BatchNorm2d(48),nn.ReLU()")
s=s.replace("(GRIDS if multiview else [(1,1)])","([(10,3)] if multiview=='single_grid' else GRIDS if multiview else [(1,1)])")
s=s.replace("self.location(spatial)","F.interpolate(self.location(spatial),size=(32,64),mode='bilinear',align_corners=False)")
s=s.replace("steps=600","steps=1500")
s=s.replace("20000000,1200","30000000,2400").replace("21000000,240","31000000,420").replace("22000000,240","32000000,420").replace("23000000,240","33000000,420")
s=s.replace("images=[];masks=[];labels=[];records=[]","images=[];masks=[];labels=[];records=[];full_masks=[];visible_masks=[]")
s=s.replace("im,mask,y,record=generate(bank,base+i,recipe)","im,mask,y,full,record=generate(bank,base+i,recipe);full_masks.append(np.uint8(full*255));visible_masks.append(np.uint8(mask*255))")
s=s.replace("(16,8),interpolation","(64,32),interpolation")
s=s.replace("print('BUILT',part,count,flush=True)","np.savez_compressed(OUT/(part+'_supervision.npz'),images=np.stack(images),full_masks=np.stack(full_masks),visible_masks=np.stack(visible_masks),labels=np.stack(labels));print('BUILT',part,count,flush=True)")
s=s.replace("return F.binary_cross_entropy_with_logits(a,y)+F.binary_cross_entropy_with_logits(z,m)+dice.mean()","return 3*F.binary_cross_entropy_with_logits(a,y,pos_weight=presence_weight)+F.binary_cross_entropy_with_logits(z,m,pos_weight=mask_weight)+dice.mean()")
s=s.replace("results={};models={}","presence_weight=((1-data['train'][2]).sum(0)/data['train'][2].sum(0).clamp_min(1)).detach();mask_weight=((1-data['train'][1]).sum((0,2,3))/data['train'][1].sum((0,2,3)).clamp_min(1)).clamp(1,20)[None,:,None,None].detach();write(OUT/'loss_weights.json',dict(presence=presence_weight.cpu().tolist(),mask=mask_weight.flatten().cpu().tolist()));results={};models={}")
s=s.replace("[('whole_image',False),('multiview',True)]","[('whole_image',False),('single_grid','single_grid'),('multiview',True)]")
s=s.replace("range(1,601)","range(1,1501)")
s=s.replace("panel=Image.new('RGB',(1000,700)","panel=Image.new('RGB',(1120,700)")
s=s.replace("10+250*col","10+280*col").replace("140+250*col","140+280*col").replace(" if col<3 else None","")
Path('run_v2_tier1_02.py').write_text(s,encoding='utf8')
